export interface CapturedTargetState {
  readonly label: string;
  readonly tier: string;
  readonly reason: string;
}

export interface NarrativeAnchor {
  readonly anchorId: string;
  readonly targetClass: AnchorTargetClass;
  /** Durable target identity — a registry identity, digest or revision;
   * never a label, a bare path or a line coordinate. */
  readonly targetId: string;
  readonly revision: string;
  /** Claim ids inside the block that this anchor supports. */
  readonly supports: readonly string[];
  /** The target's state as captured at render time; frozen, never re-read. */
  readonly captured: CapturedTargetState;
  /** Human locator (path[:line]) — display only, not identity. */
  readonly locator: string;
}

export interface NarrativeBlock {
  readonly kind: 'narrative-block';
  readonly blockId: string;
  readonly role: NarrativeClaimRole;
  readonly presentation: 'presentation-artifact';
  readonly citable: false;
  readonly claims: readonly string[];
  readonly anchors: readonly NarrativeAnchor[];
}

export interface PolarisNarrative {
  readonly kind: 'polaris-narrative';
  readonly presentation: 'presentation-artifact';
  readonly citable: false;
  readonly roles: readonly NarrativeClaimRole[];
  readonly anchorTargetClasses: readonly AnchorTargetClass[];
  readonly blocks: readonly NarrativeBlock[];
  /** Capability deep dives: band composition, verbatim state and the
   * proposals' non-anchorable, non-status-bearing futures (PWB-REQ-015). */
  readonly deepDives: readonly DeepDiveMachineForm[];
}

export interface AnchorInput {
  readonly targetClass: AnchorTargetClass;
  readonly targetId: string;
  readonly revision: string;
  readonly locator: string;
}

export interface PolarisPresentationEnvelope {
  readonly kind: typeof POLARIS_PRESENTATION_KIND;
  readonly version: 1;
  readonly presentation: 'presentation-artifact';
  readonly citable: false;
  readonly evaluation: PocModel['evaluation'];
  readonly evidence: PocModel['evaluation']['evidence'];
  readonly project: { readonly revision: string };
  readonly narrative: ReturnType<typeof renderPolarisPresentation>['narrative'];
  readonly links: NonNullable<PocModel['links']>;
}

export interface GenerationSpan {
  readonly anchorId: string;
  /** Byte offsets into this source's safe body. A redacted span separately names its original Git coordinates. */
  readonly start: number;
  readonly end: number;
  readonly text: string;
  readonly original?: { readonly start: number; readonly startLine: number; readonly endLine: number };
}

export interface GenerationSource {
  readonly sourceId: string;
  readonly repositoryId: string;
  readonly revision: string;
  readonly path: string;
  /** Null only when the named tree entry is missing or is not a blob. */
  readonly objectId: string | null;
  readonly evaluationId: string;
  readonly classificationBasis: 'body' | 'path-only';
  readonly redaction?: SourceRedaction;
  /** Present only on one contiguous piece of a blob too long to quote whole.
   * `start`/`end` are UTF-8 byte offsets into the full blob; `body` and span
   * offsets are relative to the piece, anchors use the blob offsets. For redacted
   * sources the segment covers the safe marker projection; every evidence span
   * separately carries its original Git coordinates. */
  readonly segment?: { readonly index: number; readonly count: number; readonly start: number; readonly end: number; readonly blobBytes: number };
  readonly exclusion: { readonly excluded: false } | { readonly excluded: true; readonly reason: GenerationExclusionReason };
  /** Present only for an admitted body. Never sent to a provider except in
   * the inventory envelope or a later explicitly cited span. */
  readonly body?: string;
  readonly spans: readonly GenerationSpan[];
}

export type GenerationSourceFailure =
  | 'invalid-source' | 'duplicate-source' | 'duplicate-anchor' | 'invalid-anchor'
  | 'unquotable-source' | 'body-mismatch' | 'object-mismatch' | 'source-too-long' | 'invalid-segments';

export interface EvidenceAnchor {
  readonly targetClass: 'evidence-artifact-identifier-with-integrity-digest';
  /** The blob's object identifier as Syzygy recomputed it from the bytes it read: the owning identifier and the integrity digest at once. */
  readonly identifier: string;
  /** The hash algorithm the consented revision's identifier is written in. */
  readonly algorithm: 'sha1' | 'sha256';
  /** The span's UTF-8 byte range in the blob, `[start, end)`; null for the whole blob. */
  readonly fragment: { readonly start: number; readonly end: number } | null;
  /** The pinned revision. */
  readonly targetState: string;
  /** The repository path, shown beside the anchor as a label, never as its identity. */
  readonly pathLabel: string;
}

export interface PipelineRequest {
  readonly requestId: string;
  readonly projectId: string;
  readonly snapshotId: string;
  readonly routes: Readonly<Record<GenerationStage, string>>;
  readonly startedAt: number;
  readonly budget: GenerationBudget;
  /** Complete counted population; only validated body spans may cross a
   * provider stage boundary. Permission is still a trusted port decision. */
  readonly sources: readonly GenerationSource[];
  readonly readerQuestions: unknown;
  /** Trusted operator request identities and requiredness, never model-supplied. */
  readonly requestedAssets: readonly RequestedAsset[];
  /** Which stage prompts the run sends; absent means `manifesto`. A dossier run sets `dossier`. */
  readonly promptProfile?: PromptProfile;
}

export type ClassificationRecord =
  | {
      readonly path: string;
      readonly outcome: 'classified';
      // Absent for a path-only identity whose body was deliberately not read.
      readonly contentDigest?: string;
      readonly extractionClasses: readonly string[];
      readonly policyId: string;
      readonly policyVersion: string;
      readonly detectorsRun: number;
      readonly basis: 'body' | 'path-only';
    }
  | {
      readonly path: string;
      readonly outcome: 'excluded';
      readonly exclusion: Exclusion;
      readonly unknown: FixedUnknown;
    }
  | {
      readonly path: string;
      readonly outcome: 'unavailable';
      readonly reason: UnavailableReason;
      readonly unknown: FixedUnknown;
    };

export interface ClassifiedSource<T> {
  readonly source: ManifestSource;
  readonly read: ObjectReadRecord;
  readonly record: ClassificationRecord;
  // Present only for outcome `classified`; whatever `consume` returned.
  readonly value?: T;
}

export interface PocUnknown {
  readonly label: 'Unknown';
  readonly reason: string;
  readonly closedReason: UnknownReason;
  readonly resolutionRoutes: ResolutionRoutes;
  readonly actionRoute?: PocActionRoute;
}

export interface PocUnknownSubject {
  readonly id: string;
  readonly epistemic: PocUnknown;
}

export interface PocProvenance {
  readonly kind:
    | 'repository-file'
    | 'git-revision'
    | 'dolt-revision'
    | 'manual-mapping'
    | 'materialization-record'
    | 'test-artifact-record'
    | 'project-shape-source'
    | 'owner-act';
  readonly source: string;
  readonly revision: string;
  readonly digest?: string | undefined;
}

